-- PAC and party money to (and spent for/against) federal candidates -- 867k transactions.
-- Auto-generated by scripts/gen_evidence_pages.py: 866,730 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("TRANSACTION_DT") as year, count(*) as records
from THE_LIBRARY.CAMPAIGN_FINANCE.PAC_CONTRIBUTIONS_TO_CANDIDATES
where "TRANSACTION_DT" is not null
group by 1
order by 1
